enum {
	REQUEST_QUEUED,
	REQUEST_STARTED,
	REQUEST_UNQUEUED,
	AUTHENTICATE,
	LAST_SIGNAL
};

/* Kludge to deal with the fact that CONNECT msgs come from the
 * SoupConnection rather than being queued normally.
 */
if (msg->method == SOUP_METHOD_CONNECT)
	g_signal_emit (session, signals[REQUEST_QUEUED], 0, msg);
